WITH page_type_agg AS ( SELECT wp.wp_type, ws.ws_item_sk, SUM(ws.ws_quantity) AS qty_sum, SUM(ws.ws_ext_sales_price) AS sales_sum FROM web_sales ws JOIN web_page wp ON ws.ws_web_page_sk = wp.wp_web_page_sk GROUP BY wp.wp_type, ws.ws_item_sk ) SELECT pta.wp_type, pta.ws_item_sk, pta.qty_sum, pta.sales_sum, CASE WHEN pta.sales_sum > 10000 THEN 'Top Seller' ELSE 'Regular' END AS seller_category FROM page_type_agg pta WHERE pta.qty_sum > 300 ORDER BY pta.sales_sum DESC LIMIT 10
